const schema = [{"@context":"https://schema.org","@type":"Service","name":"Accessibility compliance","serviceType":"Editorial service","provider":{"@type":"Organization","name":"Pubrica","url":"https://pubrica.com/"},"url":"https://pubrica.com/services/education-editorial-service/accessibility-compliance/","description":"Research papers, theses, textbooks and curriculum documents brought into compliance with WCAG and Section 508.","areaServed":"Worldwide","audience":{"@type":"Audience","audienceType":"Researchers, PhD scholars, research institutions, medical writers and life-science teams"}},{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":"What is accessibility compliance?","acceptedAnswer":{"@type":"Answer","text":"It means the document meets a named standard — usually WCAG and Section 508 — so that people using assistive technology can read it the way everybody else does.\n\nIn practice it comes down to structure: real headings, tagged tables, alt text that says something, equations in a readable form, and a reading order that matches the argument."}},{"@type":"Question","name":"Why does my manuscript need it?","acceptedAnswer":{"@type":"Answer","text":"Because publishers, institutions and funders increasingly require it, and a growing number check it automatically at submission. A compliance failure delays publication for reasons unconnected to your research.\n\nThe second reason is the readership. A paper with fourteen equations pasted as images has fourteen holes in it for a blind reader, and none of that shows up in a language edit."}},{"@type":"Question","name":"What are WCAG and Section 508?","acceptedAnswer":{"@type":"Answer","text":"WCAG is the W3C’s Web Content Accessibility Guidelines — the international baseline, covering screen-reader readability, colour contrast and keyboard navigation. We work to 2.2 Level AA unless your publisher specifies otherwise.\n\nSection 508 is US law requiring federal agencies to make electronic and information technology accessible, which extends to academic and scientific material they fund or procure."}},{"@type":"Question","name":"How do you handle equations?","acceptedAnswer":{"@type":"Answer","text":"This is the question that changes the quote most. Equations built in MathML or an equation editor can be made accessible directly; equations pasted as images have to be rebuilt from scratch.\n\nRebuilt properly they are read aloud correctly, searchable and resizable without blurring. Tell us how yours were made when you send the document."}},{"@type":"Question","name":"Do you check across formats and platforms?","acceptedAnswer":{"@type":"Answer","text":"Yes. Semantic formatting is applied once and then tested in the outputs you need — PDF, EPUB or HTML — because a document can validate in one and fail in another.\n\nWhere the material is a book, a chapter or e-learning content, EPUB Accessibility is usually the specification the platform checks rather than WCAG directly."}},{"@type":"Question","name":"How is this different from visual and accessibility editing?","acceptedAnswer":{"@type":"Answer","text":"This page is the document: structure, tagging, alt text, tables, equations and validation against a named standard.\n\nVisual and accessibility editing is the figures themselves — colour contrast, palettes, typography, layout and multimedia. Most projects need both, and we quote them together when they do."}}]},{"@context":"https://schema.org","@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://pubrica.com/"},{"@type":"ListItem","position":2,"name":"Services","item":"https://pubrica.com/services/"},{"@type":"ListItem","position":3,"name":"Education editorial","item":"https://pubrica.com/services/education-editorial-service/accessibility-compliance/"}]}];

